declare cid uuid;
begin
  select id into cid from public.courses where slug = 'bib-102';
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 The Letters of John and Jude$j$, $j${"readings": [{"title": "1 John 1 (King James Version)", "url": "/portal/bible/1John/1"}, {"title": "1 John 4 (King James Version)", "url": "/portal/bible/1John/4"}, {"title": "1 John 5 (King James Version)", "url": "/portal/bible/1John/5"}, {"title": "3 John 1 (King James Version)", "url": "/portal/bible/3John/1"}, {"title": "Jude 1 (King James Version)", "url": "/portal/bible/Jude/1"}], "body": "Read 1 John 1, 1 John 4, 1 John 5 and Jude 1 in the King James Version. Then read this lesson.\n\nThe apostle John, who wrote the Gospel of John, also wrote three short letters, probably when he was an old man. First John was written to help believers be sure that they have eternal life. John taught that if we walk in the light we have fellowship with one another and the blood of Jesus cleanses us from all sin, and that if we confess our sins God is faithful and just to forgive us. In chapter 4 he wrote that God is love and that we love Him because He first loved us. Second John and Third John are very short personal letters about walking in truth and showing kindness. Jude was probably written by the brother of Jesus and James. Jude urged believers to contend earnestly for the faith once delivered to the saints and ended with a beautiful blessing to the God who is able to keep us from falling.\n\nKey words: light, confess, love, victory, contend.\n\nYour task: (1) Tell why John wrote 1 John. (2) Write 1 John 1:9 in your own words. (3) Explain what Jude meant by contending for the faith.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Today we finish our study of the letters with the writings of John and Jude. The apostle John was one of the first disciples, and he wrote the Gospel of John, three short letters and the book of Revelation. He wrote his letters when he was very old, and he wrote like a loving father speaking to his children.\n\nFirst John was written so that believers could be sure of their salvation. Some false teachers were saying that Jesus had not really come in the flesh, and John answered with what he had seen with his own eyes. First John 1:7 says, But if we walk in the light, as he is in the light, we have fellowship one with another, and the blood of Jesus Christ his Son cleanseth us from all sin. Then verse 9 gives a promise for every one of us. If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness. When we fall, we do not have to hide. We can confess, and God forgives.\n\nLove is a major theme of this letter. First John 4:7 says, Beloved, let us love one another: for love is of God; and every one that loveth is born of God, and knoweth God. Verse 8 says, He that loveth not knoweth not God; for God is love. John showed us where love begins. In verse 10 he wrote, Herein is love, not that we loved God, but that he loved us, and sent his Son to be the propitiation for our sins. And verse 19 says, We love him, because he first loved us. We can love others because He loved us first.\n\nFirst John also gives victory and assurance. First John 5:4 says, For whatsoever is born of God overcometh the world: and this is the victory that overcometh the world, even our faith. And verse 13 says, These things have I written unto you that believe on the name of the Son of God; that ye may know that ye have eternal life, and that ye may believe on the name of the Son of God.\n\nSecond John and Third John are very short. Second John 1:6 says, And this is love, that we walk after his commandments. This is the commandment, That, as ye have heard from the beginning, ye should walk in it. Third John was written to a faithful friend named Gaius. Third John 1:4 says, I have no greater joy than to hear that my children walk in truth.\n\nThe last of the General Epistles is Jude, a short and urgent letter. Jude was a brother of Jesus and of James. He wanted to write about salvation, but he felt he had to warn the church about false teachers. Jude 1:3 says, Beloved, when I gave all diligence to write unto you of the common salvation, it was needful for me to write unto you, and exhort you that ye should earnestly contend for the faith which was once delivered unto the saints. To contend for the faith means to hold firmly to the truth of the gospel and defend it. Jude closed with a blessing. Jude 1:24 says, Now unto him that is able to keep you from falling, and to present you faultless before the presence of his glory with exceeding joy, And verse 25 says, To the only wise God our Saviour, be glory and majesty, dominion and power, both now and ever. Amen.\n\nYour task is to tell why John wrote First John, write 1 John 1:9 in your own words, and explain what Jude meant by contending for the faith. Then take the four question check and the Unit 5 quiz.\n\nGod is love, and He is able to keep us. Excellence, Faith, Purpose. I will see you in the next unit."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 The Letters of John and Jude$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: Faith in Action$j$, $j${"prompt": "Choose one verse from this unit: Hebrews 11:1, Hebrews 12:2, James 1:22, James 2:26, 1 Peter 5:7, 2 Peter 3:18, 1 John 1:9 or 1 John 4:19. Write one paragraph of 150 to 200 words. Quote the verse from the King James Version with the reference, explain what it meant to the first readers, and tell how a student today can put it into action this week.", "rubric": "Total 100. Accurate quotation of the verse with the reference: 20. Explains the meaning for the first readers: 30. Gives a clear and realistic application for this week: 30. Clear writing and correct conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: Faith in Action$j$);
end
$seed$;
